from PyQt5.uic import loadUi
from PyQt5.QtWidgets import QApplication, QMessageBox, QTableWidgetItem
from pickle import dump, load

def occurence(ch):
    f=open("recharge.dat","rb")
    nb=0
    eof=False
    while not eof:
        try:
            e=load(f)
            if ch==e["code"]:
                nb+=1
        except:
            eof=True
    f.close()
    return nb

def recherche(ch):
    f=open("code.txt","r")
    st=f.readline().strip()
    trouve=False
    while st!="" and not trouve:
        if ch==st:
            trouve=True
        st=f.readline().strip()
    f.close()
    return trouve

def premier(x):
    nb=0
    for i in range(2,x-1):
        if x%i==0:
            nb+=1
    return nb==0

def conb10_b2_calc0(x):
    bin=""
    while x!=0:
        bin=str(x%2)+bin
        x=x//2
    nb=0
    for i in range (len(bin)):
        if bin[i]=="0":
            nb+=1
    return nb>8

def verif_code(ch):
    xp=int(ch[:3])
    eqb=int(ch[3:8])
    div=int(ch[8:])
    return (premier(xp) and conb10_b2_calc0(eqb) and div%xp==0)

